/// The weekly boss (Core's `ScrollMonster` art).
enum WatchMonster {
    /// The boss in `state`; `variant` (0...2) changes its colours week to week.
    static func pixels(_ state: WatchMonsterState, variant: Int) -> WatchPixels {
        switch (state, ((variant % 3) + 3) % 3) {
        case (.healthy, 0): WatchSpriteData.monsterHealthy0
        case (.healthy, 1): WatchSpriteData.monsterHealthy1
        case (.healthy, _): WatchSpriteData.monsterHealthy2
        case (.hurt, 0): WatchSpriteData.monsterHurt0
        case (.hurt, 1): WatchSpriteData.monsterHurt1
        case (.hurt, _): WatchSpriteData.monsterHurt2
        case (.defeated, 0): WatchSpriteData.monsterDefeated0
        case (.defeated, 1): WatchSpriteData.monsterDefeated1
        case (.defeated, _): WatchSpriteData.monsterDefeated2
        }
    }
}

